template<typename T>
  requires(!std::same_as<T, ppc64::ondemand::document> &&
           !std::same_as<T, ppc64::ondemand::value> &&
           !std::same_as<T, ppc64::ondemand::object> &&
           !std::same_as<T, ppc64::ondemand::array>)
inline std::string to_json_string(const T& obj);
