template<typename T>
  requires(!std::same_as<T, lasx::ondemand::document> &&
           !std::same_as<T, lasx::ondemand::value> &&
           !std::same_as<T, lasx::ondemand::object> &&
           !std::same_as<T, lasx::ondemand::array>)
inline std::string to_json_string(const T& obj);
